'use strict';

// MODULES //

var tape = require( 'tape' );
var Float64Array = require( '@stdlib/array/float64' );
var isAlmostEqual = require( '@stdlib/assert/is-almost-equal-float64array' );
var ctor = require( '@stdlib/ndarray/ctor' );
var transpose = require( '@stdlib/ndarray/transpose' );
var dgemm = require( '@stdlib/blas/base/dgemm' ).ndarray;
var dorgqr = require( './../lib/dorgqr.js' );


// FIXTURES //

var UNBLOCKED = require( './fixtures/unblocked.json' );
var BLOCKED = require( './fixtures/blocked.json' );
var BLOCKED_REDUCED_NB = require( './fixtures/blocked_reduced_nb.json' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof dorgqr, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function has an arity of 9', function test( t ) {
	t.strictEqual( dorgqr.length, 9, 'returns expected value' );
	t.end();
});

tape( 'the function throws an error if provided a first argument which is not a valid order', function test( t ) {
	var values;
	var WORK;
	var TAU;
	var A;
	var i;

	A = new Float64Array( [ 1, 0, 0, 0, 1, 0 ] );
	TAU = new Float64Array( [ 2, 2 ] );
	WORK = new Float64Array( 10 );

	values = [
		'foo',
		'bar',
		'beep',
		'boop',
		-5,
		NaN,
		true,
		false,
		null,
		void 0,
		[],
		{},
		function noop() {}
	];

	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[ i ] ), TypeError, 'throws an error when provided ' + values[ i ] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			dorgqr( value, 3, 2, 2, A, 3, TAU, WORK, 10 );
		};
	}
});

