tape( 'the function generates an `M-by-N` real matrix `Q` with orthonormal columns (multiple blocks, mathematical verification)', function test( t ) {
	var WORK;
	var info;
	var TAU;
	var LDA;
	var QT;
	var A;
	var C;
	var M;
	var N;
	var K;
	var i;
	var I;
	var Q;

	M = 162;
	N = 162;
	K = 161;
	LDA = M;

	A = new Float64Array( M * N );
	TAU = new Float64Array( K );
	WORK = new Float64Array( 2 * N );

	for ( i = 0; i < N; i++ ) {
		A[ i + ( i * LDA ) ] = 1.0;
	}
	for ( i = 0; i < K; i++ ) {
		TAU[ i ] = 2.0;
	}

	info = dorgqr( 'column-major', M, N, K, A, LDA, TAU, WORK, 2 * N );

	Q = ctor( 'float64', A, [ M, N ], [ 1, LDA ], 0, 'column-major' ); // Create ndarray view of Q
	QT = transpose( Q ); // Compute Q^T
	C = new Float64Array( N * N ); // Compute C = Q^T * Q
	dgemm( 'no-transpose', 'no-transpose', N, N, M, 1.0, QT.data, QT.strides[ 0 ], QT.strides[ 1 ], QT.offset, Q.data, Q.strides[ 0 ], Q.strides[ 1 ], Q.offset, 0.0, C, 1, N, 0 ); // Compute C = Q^T * Q

	I = new Float64Array( N * N ); // Create identity matrix
	for ( i = 0; i < N; i++ ) {
		I[ i + ( i * N ) ] = 1.0;
	}

	t.strictEqual( info, 0, 'returns expected value' );
	t.strictEqual( isAlmostEqual( C, I, 1 ), true, 'Q^T * Q equals identity matrix' );
	t.end();
});
